const API='https://api.besma.co.kr/address-book';
const $=id=>document.getElementById(id);
const labels={category:'분류',organization:'기관·거래처명',region:'지역·관할',department:'부서',person:'담당자',duties:'담당업무',phone:'전화번호',fax:'팩스번호',source_url:'출처 주소',verified_on:'확인일',note:'비고'};
const max={category:60,organization:160,region:120,department:160,person:80,duties:1600,phone:40,fax:40,source_url:1000,verified_on:10,note:1000};
let caps,items=[],offset=0,total=0,editing=null,historyId=null,historyOffset=0,searchGeneration=0;
function token(){return localStorage.getItem('besma_token')||'';}
async function api(path,options={}){const t=token();if(!t)throw Error('로그인이 필요합니다.');const r=await fetch(API+path,{...options,headers:{Authorization:'Bearer '+t,'Content-Type':'application/json',...(options.headers||{})},cache:'no-store'});if(!r.ok){let v;try{v=await r.json()}catch{}throw Error(r.status===401?'로그인이 만료되었습니다. 다시 로그인해 주세요.':typeof v?.detail==='string'?v.detail:'처리하지 못했습니다. 잠시 후 다시 시도해 주세요.')}return r.json();}
function el(tag,text,cls){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;}
function button(text,fn){const b=el('button',text);b.type='button';b.onclick=fn;return b;}
function date(value){return value?new Date(value).toLocaleString('ko-KR',{timeZone:'Asia/Seoul'}):'';}
function error(e){$('status').replaceChildren(el('span',e.message+' '));if(/로그인/.test(e.message)){const a=el('a','로그인');a.href='/login';$('status').append(a);}}
async function search(){const gen=++searchGeneration;$('status').textContent='연락처를 찾고 있습니다.';try{const p=new URLSearchParams({q:$('q').value,category:$('category').value,region:$('region').value,include_inactive:$('inactive').checked,offset,limit:50});const r=await api('/contacts?'+p);if(gen!==searchGeneration)return;items=r.items;total=r.total;render();}catch(e){if(gen===searchGeneration){$('results').replaceChildren();error(e);}}}
function render(){$('status').textContent=`연락처 ${total.toLocaleString()}건`;$('results').replaceChildren();for(const x of items){const card=el('article',undefined,'contact'),info=el('div'),details=el('div'),contact=el('div');info.append(el('span',x.category+(x.active?'':' · 사용중지'),'tag'),el('h2',x.organization),el('div',[x.region,x.department,x.person].filter(Boolean).join(' · '),'muted'));details.append(el('div',x.duties,'duties'));if(x.note)details.append(el('div',x.note,'muted'));const meta=el('div',undefined,'meta');if(x.source_url&&/^https?:\/\//.test(x.source_url)){const a=el('a','출처 확인');a.href=x.source_url;a.target='_blank';a.rel='noopener noreferrer';meta.append(a,document.createTextNode(' · '));}meta.append(document.createTextNode('확인일 '+(x.verified_on||'미입력')+' · '+date(x.updated_at)+' · '+x.updated_by));details.append(meta);const a=el('a',x.phone,'phone');if(x.active)a.href='tel:'+x.phone.replace(/[^\d+]/g,'');contact.append(a);if(x.fax)contact.append(el('div','팩스 '+x.fax,'muted'));const actions=el('div',undefined,'actions');actions.append(button('번호 복사',async()=>{try{await navigator.clipboard.writeText(x.phone);$('status').textContent='전화번호를 복사했습니다.';}catch{$('status').textContent='번호를 선택해 복사해 주세요.';}}));if(caps.can_edit)actions.append(button('수정',()=>edit(x)));actions.append(button('변경 이력',()=>history(x.id)));contact.append(actions);card.append(info,details,contact);$('results').append(card);}if(!items.length)$('results').append(el('p','검색 결과가 없습니다. 다른 기관명이나 담당업무로 검색해 주세요.'));$('prev').disabled=offset===0;$('next').disabled=offset+items.length>=total;$('page').textContent=total?`${offset+1}–${offset+items.length} / ${total}`:'0';}
function edit(x=null){editing=x;$('edit-title').textContent=x?'연락처 수정':'연락처 등록';$('fields').replaceChildren();for(const[k,label]of Object.entries(labels)){const wrap=el('label',label),input=document.createElement(k==='category'?'select':['duties','note'].includes(k)?'textarea':'input');input.id='f-'+k;input.name=k;if(k==='category')for(const c of caps.categories)input.append(new Option(c,c));else{input.maxLength=max[k];input.type=k==='verified_on'?'date':k==='source_url'?'url':'text';}if(['category','organization','duties','phone'].includes(k))input.required=true;input.value=x?.[k]||'';if(k==='category'&&!input.value)input.value='거래처';wrap.append(input);if(['duties','note','source_url'].includes(k))wrap.className='wide';$('fields').append(wrap);}$('active').checked=x?x.active:true;$('reason').value='';$('edit-error').textContent='';$('editor').showModal();}
$('edit').onsubmit=async e=>{e.preventDefault();$('save').disabled=true;$('edit-error').textContent='';try{const data=Object.fromEntries(Object.keys(labels).map(k=>[k,$('f-'+k).value]));await api('/contacts'+(editing?'/'+editing.id:''),{method:editing?'PUT':'POST',body:JSON.stringify({data,reason:$('reason').value,revision:editing?.revision??null,active:$('active').checked})});$('editor').close();await search();}catch(e){$('edit-error').textContent=e.message;}finally{$('save').disabled=false;}};
async function history(id,more=false){if(!more){historyId=id;historyOffset=0;$('history-body').replaceChildren(el('p','이력을 불러오고 있습니다.'));$('history').showModal();}$('history-more').disabled=true;try{const r=await api('/contacts/'+historyId+'/history?offset='+historyOffset);if(historyId!==id)return;if(!more)$('history-body').replaceChildren();for(const x of r.items){const row=el('section',undefined,'event');row.append(el('strong',x.action+' · '+x.actor_name+' ('+x.actor_login+')'),el('p',date(x.at)+' · '+x.reason,'meta'));const dl=el('dl');for(const k of [...Object.keys(labels),'active']){const a=x.before?.[k],b=x.after?.[k];if(a===b)continue;const show=v=>k==='active'?(v?'사용 중':'사용중지'):v||'없음';dl.append(el('dt',labels[k]||'사용 여부'),el('dd',x.before?show(a)+' → '+show(b):show(b)));}row.append(dl);$('history-body').append(row);}historyOffset+=r.items.length;$('history-more').hidden=historyOffset>=r.total;}catch(e){$('history-body').append(el('p',e.message));}finally{$('history-more').disabled=false;}}
$('history-more').onclick=()=>history(historyId,true);document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$(b.dataset.close).close());$('search').onsubmit=e=>{e.preventDefault();offset=0;search();};$('prev').onclick=()=>{offset=Math.max(0,offset-50);search();};$('next').onclick=()=>{offset+=50;search();};$('add').onclick=()=>edit();
try{caps=await api('/capabilities');$('user').textContent=caps.actor_name;for(const c of caps.categories)$('category').append(new Option(c,c));$('add').hidden=!caps.can_edit;await search();}catch(e){error(e);}
